    ["Cheater!"] = "Шахрай!",
    ["Chewing on grass. Will deal [StandardDamage(2,2)] [School()] damage when done."] = "Жує траву. Завдасть [StandardDamage(2,2)] [School()] шкоди, коли закінчить.",
    ["Chitara's Unbreakable Shell"] = "Незламний Панцир Чітари",
    ["Chitara's busted up, but still unbreakable shell grows more brittle every time it takes damage.\n\nDamage taken reduced by 100% until at least [abs(abilityStateMod(74,2109))] more attacks are made against Chitana's shell."] = "Понівечений, але все ще незламний панцир Чітари стає крихкішим щоразу, коли отримує шкоду.\n\nОтримувана шкода знижена на 100%, доки по панцирю Чітари не завдадуть щонайменше ще [abs(abilityStateMod(74,2109))] атак.",
    ["Chitara's mostly unbreakable shell grows more brittle every time it takes damage.\n\nDamage taken reduced by 100% until at least [abs(abilityStateMod(74,2107))] more attacks are made against Chitana's shell."] = "Майже незламний панцир Чітари стає крихкішим щоразу, коли отримує шкоду.\n\nОтримувана шкода знижена на 100%, доки по панцирю Чітари не завдадуть щонайменше ще [abs(abilityStateMod(74,2107))] атак.",
    ["Chitara's nearly shattered, but still unbreakable shell grows more brittle every time it takes damage.\n\nDamage taken reduced by 100% until [abs(abilityStateMod(74,2110))] more attack is made against Chitana's shell."] = "Майже розтрощений, але все ще незламний панцир Чітари стає крихкішим щоразу, коли отримує шкоду.\n\nОтримувана шкода знижена на 100%, доки по панцирю Чітари не завдадуть ще [abs(abilityStateMod(74,2110))] атаку.",
    ["Chitara's shell hardens and becomes nearly unbreakable, reducing damage taken by [abs(abilityStateMod(71,2105))].\n\nLasts [duration(1,1)] |4round:rounds;."] = "Панцир Чітари твердне й стає майже незламним, знижуючи отримувану шкоду на [abs(abilityStateMod(71,2105))].\n\nТриває [duration(1,1)] |4раунд:раундів;.",
    ["Chitara's shell has been broken!\n\nDamage taken increased by [abs(abilityStateMod(24,2111))]%.\n\nDamage dealt increased by [abs(abilityStateMod(23,2111))]%."] = "Панцир Чітари зламано!\n\nОтримувана шкода підвищена на [abs(abilityStateMod(24,2111))]%.\n\nЗавдана шкода підвищена на [abs(abilityStateMod(23,2111))]%.",
    ["Chitara's slightly cracked but still unbreakable shell grows more brittle every time it takes damage.\n\nDamage taken reduced by 100% until at least [abs(abilityStateMod(74,2108))] more attacks are made against Chitana's shell."] = "Трохи тріснутий, але все ще незламний панцир Чітари стає крихкішим щоразу, коли отримує шкоду.\n\nОтримувана шкода знижена на 100%, доки по панцирю Чітари не завдадуть щонайменше ще [abs(abilityStateMod(74,2108))] атак.",
    ["Chitara's unbreakable shell grows more brittle every time it takes damage.\n\nDamage taken reduced by 100% until [abs(abilityStateMod(74,2105))] attacks are made against Chitana's shell."] = "Незламний панцир Чітари стає крихкішим щоразу, коли отримує шкоду.\n\nОтримувана шкода знижена на 100%, доки по панцирю Чітари не завдадуть [abs(abilityStateMod(74,2105))] атак.",
    ["Chromaddon ignores attacks that do more than [abs(abilityStateMod(200,1674))] damage."] = "Хромадон ігнорує атаки, що завдають більш ніж [abs(abilityStateMod(200,1674))] шкоди.",
