    ["Reduces up to [abs(abilityStateMod(71,2418))*AttackBonus()] damage from every attack against the target."] = "Зменшує до [abs(abilityStateMod(71,2418))*AttackBonus()] шкоди від кожної атаки по цілі.",
    ["Reduces up to [abs(abilityStateMod(71,309))*AttackBonus()] damage from each attack against you. \n\nLasts [duration(1,1)] |4round:rounds;."] = "Знижує шкоду кожної атаки проти вас на величину до [abs(abilityStateMod(71,309))*AttackBonus()]. \n\nТриває [duration(1,1)] |4раунд:раунди:раундів;.",
    ["Reduces up to [abs(abilityStateMod(71,309))*AttackBonus()] damage from every attack against the target."] = "Знижує шкоду кожної атаки проти цілі на величину до [abs(abilityStateMod(71,309))*AttackBonus()].",
    ["Reduces up to [abs(abilityStateMod(71,316))*AttackBonus()] damage from each attack against you and deals [StandardDamage(getProcIndex(PROC_ON_DAMAGE_TAKEN,316),1,316)] [School()] damage each time you take direct damage.\n\nLasts [duration(1,1)] |4round:rounds;."] = "Знижує шкоду кожної атаки проти вас на величину до [abs(abilityStateMod(71,316))*AttackBonus()] та завдає [StandardDamage(getProcIndex(PROC_ON_DAMAGE_TAKEN,316),1,316)] шкоди [School()] щоразу, коли ви отримуєте пряму шкоду.\n\nТриває [duration(1,1)] |4раунд:раунди:раундів;.",
    ["Reduces up to [abs(abilityStateMod(71,316))*AttackBonus()] damage from each attack and deals [FormatDamage(SimpleDamage(1,1),nil,AURAENEMY)] [School()] damage each time you take direct damage."] = "Знижує шкоду кожної атаки на величину до [abs(abilityStateMod(71,316))*AttackBonus()] та завдає [FormatDamage(SimpleDamage(1,1),nil,AURAENEMY)] шкоди [School()] щоразу, коли ви отримуєте пряму шкоду.",
    ["Reduces up to [abs(abilityStateMod(71,430))*AttackBonus()] damage from each attack against you."] = "Зменшує до [abs(abilityStateMod(71,430))*AttackBonus()] шкоди від кожної атаки проти вас.",
