    ["Reduces up to [abs(abilityStateMod(71,435))*AttackBonus()] damage from each attack against you."] = "Зменшує до [abs(abilityStateMod(71,435))*AttackBonus()] шкоди від кожної атаки проти вас.",
    ["Reduces up to [abs(abilityStateMod(71,435))*AttackBonus()] damage from each attack against you. \n\nLasts [duration(1,1)] |4round:rounds;."] = "Зменшує до [abs(abilityStateMod(71,435))*AttackBonus()] шкоди від кожної атаки проти вас. \n\nТриває [duration(1,1)] |4раунд:раунди;.",
    ["Reduces up to [abs(abilityStateMod(71,823))*AttackBonus()] damage from each attack against you. \n\nLasts [duration(1,1)] |4round:rounds;."] = "Зменшує до [abs(abilityStateMod(71,823))*AttackBonus()] шкоди від кожної атаки проти вас. \n\nТриває [duration(1,1)] |4раунд:раунди;.",
    ["Reduces up to [abs(abilityStateMod(71,823))*AttackBonus()] damage from every attack against the target."] = "Зменшує до [abs(abilityStateMod(71,823))*AttackBonus()] шкоди від кожної атаки проти цілі.",
    ["Reduces up to [abs(abilityStateMod(71,915))*AttackBonus()] damage from each attack and deals [FormatDamage(SimpleDamage(1,1),nil,AURAENEMY)] [School()] damage each time you take direct damage."] = "Зменшує до [abs(abilityStateMod(71,915))*AttackBonus()] шкоди від кожної атаки й завдає [FormatDamage(SimpleDamage(1,1),nil,AURAENEMY)] [School()] шкоди щоразу, коли ви отримуєте пряму шкоду.",
    ["Reduces up to [abs(abilityStateMod(71,959))*AttackBonus()] damage from each attack against you. \n\nLasts [duration(1,1)] |4round:rounds;."] = "Зменшує до [abs(abilityStateMod(71,959))*AttackBonus()] шкоди від кожної атаки проти вас.\n\nТриває [duration(1,1)] |4раунд:раунди:раундів;.",
    ["Reduces up to [abs(abilityStateMod(71,959))*AttackBonus()] damage from every attack against the target."] = "Зменшує до [abs(abilityStateMod(71,959))*AttackBonus()] шкоди від кожної атаки проти цілі.",
    ["Reduces your speed by 30% and increases the damage of your next attack made within [duration(1,1)] |4round:rounds; by 150%."] = "Знижує вашу швидкість на 30% і збільшує шкоду вашої наступної атаки, здійсненої протягом [duration(1,1)] |4раунд:раунди;, на 150%.",
    ["Reflecting [points(1,1)]% of the last damage amount dealt at the end of the round."] = "Відбиває [points(1,1)]% від останньої завданої шкоди наприкінці раунду.",
    ["Reforging.\nRestores health every round."] = "Перековування.\nВідновлює здоров'я щораунду.",
    ["Relaxing.\nRestores increasing health every round."] = "Відпочиває.\nЩораунду відновлює дедалі більше здоров'я.",
