    ["Releases a primal scream, increasing the user's critical strike chance by [abs(abilityStateMod(40,1053))]% for [duration(1,1)] rounds."] = "Вивільняє первісний крик, збільшуючи шанс критичного удару користувача на [abs(abilityStateMod(40,1053))]% протягом [duration(1,1)] |4раунд:раунди:раундів;.",
    ["Relish in your dominance as the greatest stuffed animal ever."] = "Насолоджується своєю перевагою як найкраща м'яка іграшка всіх часів.",
    ["Removes all buffs and debuffs from the enemy."] = "Знімає з ворога всі позитивні та негативні ефекти.",
    ["Removes all buffs and debuffs from the user's team."] = "Знімає всі позитивні й негативні ефекти з команди користувача.",
    ["Removes all buffs and debuffs from the user."] = "Знімає всі підсилення та послаблення з того, хто застосував.",
    ["Renewing Mists"] = "Цілющі Тумани",
    ["Restores [StandardDamage(1,1)] health plus half of the last hit taken by the user."] = "Відновлює [StandardDamage(1,1)] здоров'я плюс половину останнього удару, отриманого власником.",
    ["Restores [StandardDamage(1,1)] health to the user."] = "Відновлює власникові [StandardDamage(1,1)] здоров'я.",
    ["Restores [StandardDamage(1,1,267)] healing every round. Lasts [duration(1,1)] |4round:rounds;.\n\nTwice as effective in sunny weather."] = "Відновлює [StandardDamage(1,1,267)] здоров'я щораунду. Триває [duration(1,1)] |4раунд:раунди:раундів;.\n\nУдвічі ефективніше за сонячної погоди.",
    ["Restores [StandardDamage(1,1,267)] health per round.\n\nTwice as effective in Sunny weather."] = "Відновлює [StandardDamage(1,1,267)] здоров'я за раунд.\n\nУдвічі ефективніше за сонячної погоди.",
    ["Restores [StandardHealing(1,1)] health per round."] = "Відновлює [StandardHealing(1,1)] здоров'я за раунд.",
    ["Restores [StandardHealing(1,1)] health per round.\n\nPeriodically transforms this pet to take damage as if they were Elemental."] = "Відновлює [StandardHealing(1,1)] здоров'я щораунду.\n\nПеріодично перетворює цього улюбленця, аби він отримував шкоду так, ніби він Елементаль.",
    ["Restores [StandardHealing(1,1)] health to your team and calls down a cleansing rain for [duration(1,4)] rounds. \n\nDuring a cleansing rain, the duration of hostile damage over time effects is reduced by 1 round and Aquatic abilities deal 25% more damage."] = "Відновлює вашій команді [StandardHealing(1,1)] здоров'я та закликає очисний дощ на [duration(1,4)] раундів. \n\nПід час очисного дощу тривалість ворожих ефектів поступової шкоди зменшена на 1 раунд, а водні здібності завдають на 25% більше шкоди.",
    ["Restores [StandardHealing(1,1,395)] health each round."] = "Відновлює [StandardHealing(1,1,395)] здоров'я щораунду.",
    ["Restores [StandardHealing(1,1,395)] health to your active pet every round for [duration(1,1)] |4round:rounds. Persists through pet swaps."] = "Відновлює вашому активному улюбленцеві [StandardHealing(1,1,395)] здоров'я щораунду протягом [duration(1,1)] |4раунду:раундів:раундів. Зберігається при заміні улюбленців.",
    ["Restores [StandardHealing(1,1,510)] health every round."] = "Відновлює [StandardHealing(1,1,510)] здоров'я щораунду.",
    ["Restores [StandardHealing(1,1,820)] health every round for [duration(1,2)] |4round:rounds;.\n\nWhile healing, your type is transformed into [School()]."] = "Відновлює [StandardHealing(1,1,820)] здоров'я щораунду протягом [duration(1,2)] |4раунд:раунди;.\n\nПід час зцілення ваш тип перетворюється на [School()].",
    ["Restores [StandardHealing(1,5)] health and increases the maximum health of your active pet by [points(1,1,577)] per level for [duration(1,1)] rounds."] = "Відновлює [StandardHealing(1,5)] здоров'я та збільшує максимальне здоров'я вашого активного улюбленця на [points(1,1,577)] за рівень протягом [duration(1,1)] раундів.",
    ["Restores [StandardHealing(1,5)] health and removes all buffs and debuffs from the user."] = "Відновлює [StandardHealing(1,5)] здоров'я та знімає з користувача всі позитивні й негативні ефекти.",
    ["Restores [percentage(1,1)]% of the caster's health."] = "Відновлює [percentage(1,1)]% здоров'я виконавця.",
